    e3 = E("Épeler son nom : je révise l'alphabet. J'épelle mon nom et le nom de ma rue à mon voisin, qui écrit.", lines(2), ["parle", "duo", "ecris"], 1, "A", sol="Nom correctement épelé et écrit.")
    e4 = E("J'écoute 3 messages de rappel. Je note le rendez-vous.", table(["", "Chez qui ?", "Jour", "Heure"], [["1", "", "", ""], ["2", "", "", ""], ["3", "", "", ""]], ["14mm", "70mm", "50mm", "48mm"]).replace("<td></td>", '<td style="height:8mm"></td>'), ["ecoute", "ecris"], 2, "A",
           script="1. « Bonjour, ici le cabinet dentaire Dupont. Nous vous rappelons votre rendez-vous de mardi 21 novembre à 15 h 45. » — 2. « Bonjour, c'est le secrétariat de l'ophtalmologue, le docteur Vermeulen : votre rendez-vous est déplacé au vendredi 1er décembre à 9 h 15. » — 3. « Bonjour, ici la maison médicale du Parc. Votre vaccin est prévu le lundi 4 décembre à 17 h 30. »",
           sol="1. dentiste (Dupont), mardi 21/11, 15 h 45 — 2. ophtalmologue (Dr Vermeulen), vendredi 1/12, 9 h 15 — 3. maison médicale (vaccin), lundi 4/12, 17 h 30")
    b.page(f'<h2>J\'écoute bien · la voix au téléphone</h2>{e}{e2}{e3}{e4}', "Sons")

