    e4 = E("🔁 Module 2 · Les prépositions de lieu et y.", "<p>La pharmacie est ______ la boulangerie et la banque. Tu vas à la pharmacie ? — Oui, j'______ vais maintenant.</p>", ["complete"], 1, "C", sol="entre · y")
