    e2 = E("Je complète avec dois, doit ou devez.", "<div class='card big' style='line-height:2'>Je ______ dormir. · Tu ______ boire de l'eau.<br>Yonas ______ rester au lit. · Vous ______ prendre le sirop.</div>", ["complete"], 1, "C", alpha=True, sol="dois · dois · doit · devez")
    e3 = E("Je lis l'ordonnance simple et je coche.", "<div class='card' style='background:#F2FBF7'><p class='big'>Sirop : 1 cuillère, 3 fois par jour, pendant 5 jours.</p></div>" + "<p class='big'><span class='chk'></span>matin, midi, soir &nbsp; <span class='chk'></span>1 fois par jour<br><span class='chk'></span>pendant 5 jours &nbsp; <span class='chk'></span>pendant 3 jours</p>", ["lis", "coche"], 1, "B", alpha=True, sol="matin, midi, soir · pendant 5 jours")
    b.page(CP.format(t="Le temps · devoir · l'ordonnance") + e + e2 + e3, "★ Coup de pouce")
    e = E("Je prends rendez-vous avec le modèle. Je complète puis je lis avec la prof.", "<div class='card' style='background:#F2FBF7'><p class='big' style='line-height:2.1'>— Bonjour, je voudrais un <b>rendez-vous</b>, s'il vous plaît.<br>— Oui. C'est pour quoi ?<br>— J'ai mal ____________ depuis ____________ .<br>— Jeudi à 16 heures, ça va ?<br>— Oui, merci. Je m'appelle ____________ .<br>— Au revoir !</p></div>", ["complete", "parle"], 1, "A", alpha=True, sol="Dialogue complété et joué.")
